"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([["8686"],{7357(e,t,o){o.r(t),o.d(t,{metadata:()=>i,default:()=>c,frontMatter:()=>s,contentTitle:()=>r,toc:()=>l,assets:()=>d});var i=JSON.parse('{"id":"intro/motivation","title":"Motivation & planned obsolescence","description":"It is not uncommon to find listings on various marketplaces offering old Firewire audio interfaces at very reduced costs. High-quality hardware pieces that at their time had a much higher market value are now available much more accessibly because it is not trivial to get them working. Many interfaces depend on drivers that were developed with support up to Windows XP or old versions of OS X, so to use them we depend on those outdated versions of operating systems. In addition, the vast majority of laptops do not have Firewire ports to connect the interface, so one depends on using a desktop PC with a PCI-Firewire card that is compatible with the audio interface, or using a laptop that has some version of Thunderbolt to obtain a Firewire port with one or more adapters.","source":"@site/docs/intro/motivation.mdx","sourceDirName":"intro","slug":"/intro/motivation","permalink":"/docs/intro/motivation","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1},"sidebar":"tutorialSidebar","previous":{"title":"What is fuegocable?","permalink":"/docs/what-is-fuegocable"},"next":{"title":"How can Firewire audio interfaces be used today?","permalink":"/docs/intro/firewire-usage"}}'),n=o(4848),a=o(8453);let s={sidebar_position:1},r="Motivation & planned obsolescence",d={},l=[];function h(e){let t={h1:"h1",header:"header",p:"p",...(0,a.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"motivation--planned-obsolescence",children:"Motivation & planned obsolescence"})}),"\n",(0,n.jsx)(t.p,{children:"It is not uncommon to find listings on various marketplaces offering old Firewire audio interfaces at very reduced costs. High-quality hardware pieces that at their time had a much higher market value are now available much more accessibly because it is not trivial to get them working. Many interfaces depend on drivers that were developed with support up to Windows XP or old versions of OS X, so to use them we depend on those outdated versions of operating systems. In addition, the vast majority of laptops do not have Firewire ports to connect the interface, so one depends on using a desktop PC with a PCI-Firewire card that is compatible with the audio interface, or using a laptop that has some version of Thunderbolt to obtain a Firewire port with one or more adapters."}),"\n",(0,n.jsx)(t.p,{children:"Here there is an opportunity to give new purpose to obsolete hardware that in terms of audio perfectly fulfills its objective and that we can prevent from ending up unused, wasting its characteristics and harming the environment with technological waste."}),"\n",(0,n.jsx)(t.p,{children:"It is worth reflecting that unlike many computing devices that seem destined to become obsolete from their initial design, this does not seem to be the case with Firewire interfaces. As a personal reflection from the person writing this text, I believe that the industry bet on a technology like Firewire that time and various circumstances demonstrated that better alternatives could be implemented, and several years later we see how the USB standard established itself over many other standards for computing device connections. It is also worth highlighting, I believe, that even though it is logical that this type of market behavior changes occur, the industry in general does nothing to save products that becomes obsolet. Sure, they shouldn't get any profit from doing so, but profitability is a label that is not compatible with the sustainability of our human life, since we are talking about compatibilities. These efforts in which the industry does not get involved today are not without cost, mainly for individuals who work in isolation. For this very reason, fuegocable is established from the beginning as an open source project, to allow a community, large or small, to establish itself around it and in small or larger steps build something that is beneficial to that community, such as dusting off old audio interfaces to give them new life and, pretty sure, new songs to be played or recorded."})]})}function c(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(h,{...e})}):h(e)}},8453(e,t,o){o.d(t,{R:()=>s,x:()=>r});var i=o(6540);let n={},a=i.createContext(n);function s(e){let t=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:s(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);